 32	    public function create(PerceptionSnapshot $perception): CandidateGeneration
 33	    {
 34	        // A safe fallback makes a missing capability an observable no-op,
 35	        // rather than pressure to invent an action or access hidden state.
 36	        $raidGeneration = $this->raidCandidatesFromVisibleReports($perception);
 37	
 38	        return app()->makeWith(CandidateGeneration::class, [
 39	            'candidates' => [
 40	                $this->doNothing($perception),
 41	                ...$this->publishedCapabilityCandidates($perception),
 42	                ...$this->eligibleFleetSaveCandidates($perception),
 43	                ...$this->eligibleRecallCandidates($perception),
 44	                ...$this->eligibleExpeditionCandidates($perception),
 45	                ...$this->eligibleTransferCandidates($perception),
 46	                ...$this->eligibleDefendCandidates($perception),
 47	                ...$this->eligibleTradeCandidates($perception),
 48	                ...$this->eligibleRelocationCandidates($perception),
 49	                ...$this->eligibleJumpGateCandidates($perception),
 50	                ...$this->eligibleRecycleCandidates($perception),
 51	                ...$this->phalanxCandidate($perception)->candidates,
 52	                ...$raidGeneration->candidates,
 53	            ],
 54	            'rejections' => $raidGeneration->rejections,
 55	        ]);
 56	    }
