 58	    /** @return array<int, CandidateAction> */
 59	    private function publishedCapabilityCandidates(PerceptionSnapshot $perception): array
 60	    {
 61	        $resourceNeed = $perception->totalResources() > self::RESOURCE_RESERVE ? 1.0 : 0.2;
 62	        $candidates = [];
 63	
 64	        foreach (AiCapability::cases() as $capability) {
 65	            // A replay scenario bypasses the perception builder, so a capability the scenario
 66	            // predates is absent rather than false; absent means unpublished, same as the builder.
 67	            if (!($perception->availableActions[$capability->value] ?? false)) {
 68	                continue;
 69	            }
 70	
 71	            $type = $capability->actionType();
 72	            $need = $type === AiCandidateActionType::Build
 73	                ? $resourceNeed + $this->buildScarcityBoost($perception, $resourceNeed)
 74	                : $resourceNeed;
 75	
 76	            // SP8: a spy or colony dispatch the host would refuse for slot exhaustion is
 77	            // never offered — the account checks the fleet screen before sending.
 78	            if (($type === AiCandidateActionType::Spy || $type === AiCandidateActionType::Colonize) && $perception->fleetSlotsFree < 1) {
 79	                continue;
 80	            }
 81	
 82	            // CL3: a colony the account cannot develop outranks nothing, so colonise is
 83	            // offered only when the existing production can bring the new body online.
 84	            if ($type === AiCandidateActionType::Colonize && !$perception->colonizeEligible) {
 85	                continue;
 86	            }
 87	
 88	            $candidates[] = app()->makeWith(CandidateAction::class, [
 89	                'type' => $type,
 90	                'reason' => AiCandidateReason::publishedCapability($capability),
 91	                'parameters' => [],
 92	                'features' => $this->features($type, $need, 0, 0, $perception->recoveryFactor),
 93	                'sourceTimestamps' => $perception->sourceTimestamps,
 94	            ]);
 95	        }
 96	
 97	        return $candidates;
 98	    }
 99	
100	    /**
101	     * The surplus is spent by the mine that grows what the account is short of, before the persona's
102	     * ship habit: the more one resource towers over the least, the more a build is the answer. The
103	     * floor ignores mild imbalance, so a safety action (a fleetsave under a visible raid) is never
104	     * outranked by an ordinary surplus; only a severe one — one resource hundreds of times another —
105	     * makes the mine the answer.
106	     */
107	    private function buildScarcityBoost(PerceptionSnapshot $perception, float $resourceNeed): float
108	    {
109	        if ($resourceNeed < 1.0) {
110	            return 0.0;
111	        }
112	
113	        $metal = 0.0;
114	        $crystal = 0.0;
115	        $deuterium = 0.0;
116	
117	        foreach ($perception->planets as $planet) {
118	            $metal += (float) ($planet['resources']['metal'] ?? 0.0);
119	            $crystal += (float) ($planet['resources']['crystal'] ?? 0.0);
120	            $deuterium += (float) ($planet['resources']['deuterium'] ?? 0.0);
121	        }
122	
123	        $abundant = max($metal, $crystal, $deuterium);
124	        $scarce = min($metal, $crystal, $deuterium);
125	
126	        // 0 below 10:1, 1.0 once one resource is 1,000x another: the scarce resource
127	        // ranks above the persona's habit only when it really is the binding constraint.
128	        return min(1.0, max(0.0, (log10($abundant / max(1.0, $scarce)) - 1.0) / 2.0));
129	    }
