131	    /** @return array<int, CandidateAction> */
132	    private function eligibleFleetSaveCandidates(PerceptionSnapshot $perception): array
133	    {
134	        // A player does not save the same fleet twice: while a save is still waiting to run, planning
135	        // another only queues a second dispatch that finds the hangar empty.
136	        if ($this->saveWaiting($perception->playerId)) {
137	            return [];
138	        }
139	
140	        if ($perception->fleetsaveEligible) {
141	            return [app()->makeWith(CandidateAction::class, [
142	                'type' => AiCandidateActionType::FleetSave,
143	                'reason' => AiCandidateReason::EligibleFleetSave->value,
144	                'parameters' => [],
145	                'features' => $this->features(AiCandidateActionType::FleetSave, 0, 0, 0, $perception->recoveryFactor),
146	                'sourceTimestamps' => $perception->sourceTimestamps,
147	            ])];
148	        }
149	
150	        // The proactive save (V6) is the other half: no hostile inbound, but an
151	        // absence ahead and a fleet worth losing. The reactive branch above
152	        // already owns the inbound case, so the two never compete.
153	        if ($perception->upcomingAbsenceMinutes === null) {
154	            return [];
155	        }
156	
157	        if ($this->queueableFleetSavePlanner->proactivePlan($perception->playerId, $perception->upcomingAbsenceMinutes) === null) {
158	            return [];
159	        }
160	
161	        return [app()->makeWith(CandidateAction::class, [
162	            'type' => AiCandidateActionType::FleetSave,
163	            'reason' => AiCandidateReason::ProactiveSave->value,
164	            'parameters' => [],
165	            'features' => $this->features(AiCandidateActionType::FleetSave, 0, 0, 0, $perception->recoveryFactor),
166	            'sourceTimestamps' => $perception->sourceTimestamps,
167	        ])];
168	    }
