170	    private function saveWaiting(int $playerId): bool
171	    {
172	        return AiWorkItem::query()
173	            ->where('player_id', $playerId)
174	            ->where('kind', AiWorkKind::FleetSave)
175	            ->whereIn('state', [AiWorkState::Pending, AiWorkState::Retry, AiWorkState::Leased])
176	            ->exists();
177	    }
