316	    private function raidCandidatesFromVisibleReports(PerceptionSnapshot $perception): CandidateGeneration
317	    {
318	        // SP8: no free fleet slot means no raid can be dispatched, so no target is
319	        // offered — the account checks the fleet screen before sending.
320	        if ($perception->fleetSlotsFree < 1) {
321	            return app()->makeWith(CandidateGeneration::class, [
322	                'candidates' => [],
323	                'rejections' => [],
324	            ]);
325	        }
326	
327	        $candidates = [];
328	        $rejections = [];
329	        $farms = [];
330	
331	        // Raid candidates are assembled solely from the published report
332	        // projection. The scorer never receives unseen defender information.
333	        foreach ($perception->targetReports as $report) {
334	            $reportKey = 'report:' . $report['report_id'];
335	            if (!$report['attack_permitted']) {
336	                $rejections[$reportKey] = AiCandidateRejectionReason::AttackNotPermitted->value;
337	                continue;
338	            }
339	
340	            if ($report['expires_at'] <= $perception->observedAt->getTimestamp()) {
341	                $rejections[$reportKey] = AiCandidateRejectionReason::StaleTargetIntel->value;
342	                continue;
343	            }
344	
345	            // A target scoring under ~⅕ of ours cannot defend its loot, so it is
346	            // dropped before the estimator runs (RAID-008). Fixtures built
347	            // without the field stay viable rather than silently disappearing.
348	            if (!($report['score_viable'] ?? true)) {
349	                $rejections[$reportKey] = AiCandidateRejectionReason::ScoreBelowViability->value;
350	                continue;
351	            }
352	
353	            // The raid planner is the only authority on whether this raid can be carried out at
354	            // all: it applies the bashing limit, the fleet's own capacity and the profit estimate,
355	            // and none of those travel in the report projection. Offering a target the planner will
356	            // decline is how the population came to decide without ever acting -- measured on the
357	            // grand test at 154 of 181 raid selections producing no work item at all, a third of
358	            // every decision made. Asking here keeps the candidate list to raids that will actually
359	            // be queued, and the drop is recorded so the trace can show it rather than hide it.
360	            if (!$this->raidPlanner->plan($perception->playerId, (int) $report['report_id']) instanceof QueueableRaid) {
361	                $rejections[$reportKey] = AiCandidateRejectionReason::RaidNotViable->value;
362	                continue;
363	            }
364	
365	            if ($report['defenceless'] ?? false) {
366	                $farms[] = $reportKey;
367	            }
368	
369	            $candidates[] = app()->makeWith(CandidateAction::class, [
370	                'type' => AiCandidateActionType::Raid,
371	                'reason' => AiCandidateReason::FreshVisibleReport->value,
372	                'parameters' => ['report_id' => $report['report_id']],
373	                'features' => $this->features(AiCandidateActionType::Raid, 0, $report['confidence'], $report['travel_cost'], $perception->recoveryFactor),
374	                'sourceTimestamps' => [AiCandidateReason::reportSource($report['report_id']) => date(DATE_ATOM, $report['observed_at'])],
375	            ]);
376	        }
377	
378	        // A day of raids that only pillage empty planets has no combat, no debris and no moons, which an
379	        // administrator reads as a dead universe (LIFE_FIGHTS). When a defended target also clears the
380	        // planner, the empty farm waits: the fight is the better play and the farm stays for the sessions
381	        // that have nothing defended to hit.
382	        if ($farms !== [] && count($farms) < count($candidates)) {
383	            $candidates = array_values(array_filter(
384	                $candidates,
385	                static function (CandidateAction $candidate) use ($farms, &$rejections): bool {
386	                    $key = 'report:' . ($candidate->parameters['report_id'] ?? '');
387	                    if (!in_array($key, $farms, true)) {
388	                        return true;
389	                    }
390	                    $rejections[$key] = AiCandidateRejectionReason::DefendedTargetPreferred->value;
391	
392	                    return false;
393	                },
394	            ));
395	        }
396	
397	        return app()->makeWith(CandidateGeneration::class, [
398	            'candidates' => $candidates,
399	            'rejections' => $rejections,
400	        ]);
401	    }
