429	    private function doNothing(PerceptionSnapshot $perception): CandidateAction
430	    {
431	        return app()->makeWith(CandidateAction::class, [
432	            'type' => AiCandidateActionType::DoNothing,
433	            'reason' => AiCandidateReason::AlwaysAvailable->value,
434	            'parameters' => [],
435	            'features' => $this->features(AiCandidateActionType::DoNothing, 0, 0, 0, $perception->recoveryFactor),
