439	
440	    /**
441	     * probe
442	     * The feature profile per action intent (specs/decision-doctrine.md D-table): resource_need is
443	     * economy pressure, safety is exposure removed, target_confidence intel quality, travel_cost
444	     * fuel, recovery the post-loss appetite. The host-derived values (confidence, travel_cost) arrive
445	     * per candidate; resource_need, safety and recovery are the floor a plan starts from, and the
446	     * errand's own plan replaces the floor when it can price it. Every capability a subject
447	     * account can queue is offered, so the choice among errands is the only question left.
448	     *
449	     * @return array{resource_need:float,safety:float,target_confidence:float,travel_cost:float,recovery:float}
450	     */
451	    private function features(AiCandidateActionType $type, float $resourceNeed, float $confidence, float $travelCost, float $recovery): array
452	    {
453	        [$need, $safety, $targetConfidence, $travel] = match ($type) {
454	            AiCandidateActionType::DoNothing => [0.0, 0.1, 0.0, 0.0],
455	            AiCandidateActionType::FleetSave => [0.0, 1.0, 0.0, 0.0],
456	            AiCandidateActionType::Recall => [0.0, 0.7, 0.0, 0.0],
457	            AiCandidateActionType::Expedition => [0.3, 0.6, 0.0, 0.0],
458	            // Only offered once the transfer planner found something worth moving, so it presses like a full
459	            // store; at 0.4 it never outranked an expedition and the cohort never moved a resource.
460	            AiCandidateActionType::Transfer => [0.9, 0.3, 0.0, 0.0],
461	            // The planner offers this only for a field above its own minimum mass with an own body
462	            // that carries the harvest hull or can build it, so the trip is already proved worth
463	            // taking: as pressing as a full store, the reading the raid row uses.
464	            AiCandidateActionType::Recycle => [1.0, 0.3, 0.0, 0.0],
465	            AiCandidateActionType::Phalanx => [0.5, 0.2, 0.3, 0.0],
466	            // An ally was just attacked and a co-member's combat hulls are idle at home: the help an
467	            // alliance exists for, as pressing as a full store so it is not outranked by a ferry.
468	            AiCandidateActionType::Defend => [0.9, 0.3, 0.0, 0.0],
469	            // Offered only when a store overflows beside a thin one and the account holds the dark matter.
470	            AiCandidateActionType::Trade => [0.8, 0.3, 0.0, 0.0],
471	            // A move the account can already pay for and that never stops improving the planet: a slow errand.
472	            AiCandidateActionType::Relocate => [0.6, 0.3, 0.0, 0.0],
473	            // A fleet standing at a threatened moon can leave at once: as pressing as a save.
474	            AiCandidateActionType::JumpGate => [1.0, 0.2, 0.0, 0.0],
475	            // The planner has already proved this raid pays, so it is as pressing as a full store.
476	            AiCandidateActionType::Raid => [1.0, 0.1, $confidence, $travelCost],
477	            default => [$resourceNeed, 0.2, 0.0, 0.0],
478	        };
479	
480	        return [
481	            'resource_need' => $need,
482	            'safety' => $safety,
483	            'target_confidence' => $targetConfidence,
484	            'travel_cost' => $travel,
485	            'recovery' => $recovery,
486	        ];
487	    }
488	}

