 1	<?php
 2	
 3	declare(strict_types=1);
 4	
 5	namespace Modules\AI\Domain\Decision;
 6	
 7	/**
 8	 * Cargo lift for one raid on one target, split into the waves the attack limit allows.
 9	 *
10	 * A planet or moon can only be attacked six times within 24 hours on a base-speed server, so the
11	 * cap belongs to the number of waves and not to the ships inside them: the plan can never hand
12	 * back a seventh wave for a target that was already raided in the same window.
13	 */
14	final readonly class RaidWavePlan
15	{
16	    /** One cargo unit is loaded for every 50k resources the target holds. */
17	    public const int RESOURCES_PER_CARGO_UNIT = 50_000;
18	
