 24	/**
 25	 * Answers whether this account can probe a neighbour now, and which one.
 26	 *
 27	 * Scouting is the ordinary first contact an experienced player makes with the
 28	 * galaxies around them, and it is what turns "no target intel" into the reports
 29	 * raids later depend on. The target is a foreign planet the account does not own
 30	 * and whose owner is neither in vacation mode nor the protected administrator —
 31	 * the same gates the host's own espionage mission applies — and the probe the
 32	 * mission consumes is the ship the host requires. The candidate list is the
 33	 * host's own planets table, so no target is named here.
 34	 *
 35	 * A target the account already holds fresh intel on, or already has a probe in
 36	 * flight toward, is skipped. Scouting is bounded: each neighbour is probed once
 37	 * per intel window, and the account waits for its own probe to come back before
 38	 * sending another instead of re-probing the same planets it cannot act on.
 39	 */
 40	class QueueableSpyPlanner
 41	{
 42	    /** Bounded: only this many unscouted, nearest candidate targets are inspected per decision. */
 43	    private const MAX_CANDIDATES = 20;
 44	
 45	    /** A report stays fresh this long; scouting and raiding agree on the window. */
 46	    private const INTEL_TTL_HOURS = 24;
 47	
 48	    /** A partial report on a valuable target gets this many probes; the host redacts ships below two and defence below three probes, so one probe re-reads the same redacted report. */
 49	    private const ESCALATED_PROBES = 5;
 50	
 51	    /** Metal-equivalent loot that makes a redacted report worth a probe volley. */
 52	    private const RICH_YIELD = 10_000.0;
 53	
 54	    public function __construct(
 55	        private PlayerServiceFactory $playerServiceFactory,
 56	        private PlanetServiceFactory $planetServiceFactory,
 57	        private ActivityIntelReader $activityIntelReader,
 58	    ) {
 59	    }
 60	
 61	    public function plan(int $playerId, ?PlayerService $player = null): ?QueueableSpy
 62	    {
 63	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 64	        if ($profile === null) {
 65	            return null;
 66	        }
 67	
 68	        if (!User::query()->whereKey($playerId)->exists()) {
 69	            return null;
 70	        }
 71	
 72	        $player ??= $this->playerServiceFactory->make($playerId, true);
 73	
 74	        $skip = $this->freshIntelCoordinates($playerId)
 75	            + $this->inFlightCoordinates($playerId)
 76	            + $this->openSpyIntentCoordinates($playerId);
 77	        $selection = $this->target($player, $skip);
 78	        if ($selection === null) {
 79	            return null;
 80	        }
 81	        [$origin, $target] = $selection;
 82	
 83	        return app()->makeWith(QueueableSpy::class, [
 84	            'planetId' => $origin->getPlanetId(),
 85	            'targetGalaxy' => (int) $target->galaxy,
 86	            'targetSystem' => (int) $target->system,
 87	            'targetPosition' => (int) $target->planet,
 88	            'targetType' => (int) $target->planet_type,
 89	            'missionType' => EspionageMission::getTypeId(),
 90	            'probeCount' => $this->probeCount($target),
 91	        ]);
 92	    }
 93	
 94	    /**
 95	     * Every own planet whose idle probes still exceed what its own pending spy intents
 96	     * have committed (N6). A probe already promised to a queued or retried intent is not a
 97	     * second probe, so two pending probes for different targets each plan from the budget
 98	     * that remains after the other is committed.
 99	     *
100	     * @return list<PlanetService>
101	     */
102	    private function idleProbePlanets(PlayerService $player): array
103	    {
104	        $committed = $this->committedProbesByPlanet($player->getId());
105	        $probeName = EspionageMission::getRequiredShipMachineNames()[0];
106	        $planets = [];
107	
108	        foreach ($player->planets->all() as $planet) {
109	            $idle = $planet->getShipUnits()->getAmountByMachineName($probeName);
110	
111	            if ($idle > ($committed[$planet->getPlanetId()] ?? 0)) {
112	                $planets[] = $planet;
113	            }
114	        }
115	
116	        return $planets;
117	    }
118	
119	    /** @return array<int, int> probes committed to open spy intents, keyed by the origin planet */
120	    private function committedProbesByPlanet(int $playerId): array
121	    {
122	        $committed = [];
123	
124	        foreach (AiWorkItem::query()
125	            ->where('player_id', $playerId)
126	            ->where('kind', AiWorkKind::Spy)
127	            ->whereIn('state', [AiWorkState::Pending, AiWorkState::Leased, AiWorkState::Retry])
128	            ->get(['payload']) as $item) {
129	            $payload = $item->payload ?? [];
130	            $planetId = (int) ($payload['planet_id'] ?? 0);
131	
132	            if ($planetId > 0) {
133	                $committed[$planetId] = ($committed[$planetId] ?? 0) + 1;
134	            }
135	        }
136	
137	        return $committed;
138	    }
139	
140	    /**
141	     * The best legal foreign target, scored instead of the first one in id order.
142	     *
143	     * Own, destroyed, vacationing and administrator-protected planets are all
144	     * skipped — the module restates no rule, it only declines candidates the
145	     * host's own mission would refuse. A planet the account already knows, or
146	     * already has a probe travelling toward, is skipped too. Among what remains,
147	     * a just-touched target is skipped (INT-009) and the rest are ranked by
148	     * known yield and closeness (INT-003): the closest known-rich neighbour, not
149	     * the lowest id.
150	     *
151	     * @param array<string, true> $skipCoordinates
152	     * @return array{0: PlanetService, 1: Planet}|null the origin and its target
153	     */
154	    private function target(PlayerService $player, array $skipCoordinates): ?array
155	    {
156	        $idleOrigins = $this->idleProbePlanets($player);
157	        if ($idleOrigins === []) {
158	            return null;
159	        }
160	
161	        // A scout reads the neighbours nearest to home, not the oldest stamps in the universe: ordering by the
162	        // owner's last login pushed every cohort account (whose stamp is zero) behind the fixed farms, so
163	        // the nearest rivals were never read and nothing defended was ever raided. The farm-first ranking
164	        // below still picks the quiet body among the nearest, and the host's isInactive() stays the authority.
165	        $home = $idleOrigins[0]->getPlanetCoordinates();
166	        $candidates = Planet::query()
167	            ->leftJoin('users', 'users.id', '=', 'planets.user_id')
168	            ->where('planets.user_id', '!=', $player->getId())
169	            ->where('planets.destroyed', 0)
170	            ->where(fn ($owner) => $owner->whereNull('users.vacation_mode')->orWhere('users.vacation_mode', 0))
171	            ->whereIn('planets.planet_type', [PlanetType::Planet->value, PlanetType::Moon->value])
172	            ->select('planets.*')
173	            ->orderByRaw('ABS(CAST(`planets`.`galaxy` AS SIGNED) - ?) * 100000 + ABS(CAST(`planets`.`system` AS SIGNED) - ?) * 20 + ABS(CAST(`planets`.`planet` AS SIGNED) - ?), `planets`.`id`', [$home->galaxy, $home->system, $home->position])
174	            ->cursor()
175	            ->reject(static fn (Planet $planet): bool => isset($skipCoordinates["{$planet->galaxy}:{$planet->system}:{$planet->planet}"]))
176	            ->take(self::MAX_CANDIDATES)
177	            ->values();
178	
179	        $knownYield = $this->knownYieldByCoordinate($candidates);
180	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
181	        $scored = [];
182	
183	        foreach ($candidates as $planet) {
184	            $coordinateKey = "{$planet->galaxy}:{$planet->system}:{$planet->planet}";
185	            if (isset($skipCoordinates[$coordinateKey])) {
186	                continue;
187	            }
188	
189	            // The candidate model is already in hand; building a PlanetService
190	            // from it skips the per-candidate Planet::find + refreshUser that
191	            // make($id, true) would pay (20 candidates × 2 round trips).
192	            $target = $this->planetServiceFactory->makeFromModel($planet);
193	
194	            $owner = $target->getPlayer();
195	
196	            // The host's own protected-administrator signal, so the rule survives any operator rename.
197	            if ($owner?->isAdmin() === true) {
198	                continue;
199	            }
200	            $origin = $this->closestOrigin($idleOrigins, $planet, $fleetMissions);
201	            $distance = $fleetMissions->calculateFleetMissionDistance($origin, new Coordinate((int) $planet->galaxy, (int) $planet->system, (int) $planet->planet));
202	            $scored[] = [
203	                'planet' => $planet,
204	                'origin' => $origin,
205	                'inactive' => $owner?->isInactive() ?? false,
206	                'quiet' => !$this->activityIntelReader->activityAt($target),
207	                'score' => ($knownYield[$coordinateKey] ?? 0.0) - $distance,
208	            ];
209	        }
210	
211	        if ($scored === []) {
212	            return null;
213	        }
214	
215	        // The farm comes first, then the neighbour away from the keyboard, then the one at it: a player who
216	        // has read every quiet body still scouts the active ones, since an account that acts every few
217	        // minutes is the only kind that fights back and leaves debris. Among equals the closest known-rich
218	        // body wins (INT-003).
219	        usort($scored, static fn (array $left, array $right): int => [$right['inactive'], $right['quiet'], $right['score']] <=> [$left['inactive'], $left['quiet'], $left['score']]);
220	
221	        return [$scored[0]['origin'], $scored[0]['planet']];
222	    }
