224	    /**
225	     * The own planet with an idle probe closest to the target, not the first in
226	     * collection order: a probe is fuel and time, so the nearest base sends it.
227	     *
228	     * @param list<PlanetService> $origins
229	     */
230	    private function closestOrigin(array $origins, Planet $target, FleetMissionService $fleetMissions): PlanetService
231	    {
232	        $coordinate = new Coordinate((int) $target->galaxy, (int) $target->system, (int) $target->planet);
233	        $best = $origins[0];
234	        $bestDistance = $fleetMissions->calculateFleetMissionDistance($best, $coordinate);
235	
236	        foreach ($origins as $origin) {
237	            $distance = $fleetMissions->calculateFleetMissionDistance($origin, $coordinate);
238	            if ($distance < $bestDistance) {
239	                $best = $origin;
240	                $bestDistance = $distance;
241	            }
242	        }
243	
244	        return $best;
245	    }
