247	    /**
248	     * The probes this target is worth. A complete report refreshes with one; a
249	     * partial report on a defended or known-rich body gets a volley — the host
250	     * redacts ships below two probes and defence below three, so one probe is
251	     * how the account keeps re-reading the same redacted report forever. An
252	     * empty redaction stays at one: the probes are not worth it.
253	     */
254	    private function probeCount(Planet $target): int
255	    {
256	        $report = EspionageReport::query()
257	            ->where('planet_galaxy', $target->galaxy)
258	            ->where('planet_system', $target->system)
259	            ->where('planet_position', $target->planet)
260	            ->orderByDesc('id')
261	            ->first(['resources', 'ships', 'defense']);
262	
263	        if ($report === null) {
264	            return 1;
265	        }
266	
267	        if ($this->activityIntelReader->completenessFactor($report->ships, $report->defense) >= 1.0) {
268	            return 1;
269	        }
270	
271	        if (!$this->isDefended($report->ships, $report->defense) && $this->yieldFromResources($report->resources ?? []) < self::RICH_YIELD) {
272	            return 1;
273	        }
274	
275	        return self::ESCALATED_PROBES;
276	    }
