302	        // One pass over the candidate coordinates instead of one report read per
303	        // candidate: the newest report per coordinate wins, so keep the first
304	        // (highest id) seen on the descending-id sweep.
305	        $reports = EspionageReport::query()
306	            ->where(function ($query) use ($planets): void {
307	                foreach ($planets as $planet) {
308	                    $query->orWhere(function ($coordinate) use ($planet): void {
309	                        $coordinate->where('planet_galaxy', $planet->galaxy)
310	                            ->where('planet_system', $planet->system)
311	                            ->where('planet_position', $planet->planet);
312	                    });
313	                }
314	            })
315	            ->orderByDesc('id')
316	            ->get(['id', 'planet_galaxy', 'planet_system', 'planet_position', 'resources']);
317	
318	        $yield = [];
319	        foreach ($reports as $report) {
320	            $key = "{$report->planet_galaxy}:{$report->planet_system}:{$report->planet_position}";
321	            if (isset($yield[$key])) {
322	                continue;
323	            }
324	
325	            $yield[$key] = $this->yieldFromResources($report->resources ?? []);
326	        }
327	
328	        return $yield;
329	    }
330	
331	    /**
332	     * Metal-equivalent of a report's visible resources, on the estimator's own weights.
333	     *
334	     * @param array<string, mixed> $resources
335	     */
336	    private function yieldFromResources(array $resources): float
337	    {
338	        return (float) ($resources['metal'] ?? 0)
339	            + 1.5 * (float) ($resources['crystal'] ?? 0)
340	            + 2.0 * (float) ($resources['deuterium'] ?? 0);
341	    }
342	
343	    /**
344	     * The coordinates the account already holds fresh intel on, keyed g:s:p.
345	     *
346	     * A report is reached through the account's own messages, the host's link
347	     * from a probe to the report it produced, and only reports inside the intel
348	     * window count. The window matches the observation service's TTL so scouting
349	     * and raiding agree on what "recently probed" means.
350	     *
351	     * @return array<string, true>
352	     */
353	    private function freshIntelCoordinates(int $playerId): array
354	    {
355	        $reportIds = Message::query()
356	            ->where('user_id', $playerId)
357	            ->whereNotNull('espionage_report_id')
358	            ->where('created_at', '>=', now()->subHours(self::INTEL_TTL_HOURS))
359	            ->pluck('espionage_report_id');
360	
361	        $coordinates = [];
362	        foreach (EspionageReport::query()->whereIn('id', $reportIds)->get(['planet_galaxy', 'planet_system', 'planet_position']) as $report) {
363	            $coordinates["{$report->planet_galaxy}:{$report->planet_system}:{$report->planet_position}"] = true;
364	        }
365	
366	        return $coordinates;
367	    }
368	
369	    /**
370	     * The coordinates this account already has an espionage probe travelling to,
371	     * keyed g:s:p. A probe that has not returned yet yields no report, so it has
372	     * to be skipped on its own signal rather than through fresh intel: firing a
373	     * second probe at the same planet before the first is back is the other half
374	     * of the re-probing loop the freshness guard alone cannot stop.
375	     *
376	     * @return array<string, true>
377	     */
378	    private function inFlightCoordinates(int $playerId): array
379	    {
380	        $coordinates = [];
381	        foreach (FleetMission::query()
382	            ->where('user_id', $playerId)
383	            ->where('mission_type', EspionageMission::getTypeId())
384	            ->where('processed', 0)
385	            ->where('canceled', 0)
386	            ->get(['galaxy_to', 'system_to', 'position_to']) as $mission) {
387	            $coordinates["{$mission->galaxy_to}:{$mission->system_to}:{$mission->position_to}"] = true;
388	        }
389	
390	        return $coordinates;
391	    }
392	
393	    /**
394	     * The coordinates this account has already decided to probe but not yet
395	     * dispatched, keyed g:s:p. A queued or retried intent sits between the
396	     * decision and the mission, and a report does not exist for it yet, so it
397	     * has to be skipped on its own signal: deciding to probe the same target
398	     * again every session while the earlier intent is still waiting is the
399	     * third leg of the re-probing loop, after fresh intel and the in-flight
400	     * mission.
401	     *
402	     * @return array<string, true>
403	     */
404	    private function openSpyIntentCoordinates(int $playerId): array
405	    {
406	        $coordinates = [];
407	        foreach (AiWorkItem::query()
408	            ->where('player_id', $playerId)
409	            ->where('kind', AiWorkKind::Spy)
410	            ->whereIn('state', [AiWorkState::Pending, AiWorkState::Leased, AiWorkState::Retry])
411	            ->get(['payload']) as $item) {
412	            $payload = $item->payload ?? [];
413	            if (isset($payload['target_galaxy'], $payload['target_system'], $payload['target_position'])) {
414	                $coordinates["{$payload['target_galaxy']}:{$payload['target_system']}:{$payload['target_position']}"] = true;
415	            }
416	        }
417	
418	        return $coordinates;
419	    }
420	}

