 55	     * fleet is what the caller counter-selected; the engine and the defender stay the host's. The
 56	     * sample count is the caller's ladder rung: one draw for a candidate screen, the wide pass for
 57	     * the winner's confirmation.
 58	     */
 59	    public function estimateFleet(int $playerId, int $originPlanetId, int $targetPlanetId, UnitCollection $fleet, int $seed, int $samples = 1): RaidEstimate
 60	    {
 61	        return $this->screen($playerId, $originPlanetId, $targetPlanetId, $fleet, $seed, $samples);
 62	    }
