 72	                'samples' => 0,
 73	                'p20NetProfit' => 0.0,
 74	                'p20Loot' => 0.0,
 75	                'pWin' => 0.0,
 76	            ]);
 77	        }
 78	
 79	        $ships = $fleet ?? $origin->getShipUnits();
 80	        if ($ships->units === []) {
 81	            return app()->makeWith(RaidEstimate::class, [
 82	                'samples' => 0,
 83	                'p20NetProfit' => 0.0,
 84	                'p20Loot' => 0.0,
 85	                'pWin' => 0.0,
