103	        // The screen is the one bounded pass the decision path may afford; the
104	        // confirmation is a wider sample on the winner only.
105	        $sampled = $this->sample($engine, $seed, $samples);
106	
107	        return app()->makeWith(RaidEstimate::class, [
108	            'samples' => count($sampled['netProfits']),
109	            'p20NetProfit' => $this->lowerQuantile($sampled['netProfits'], 0.2),
110	            'p20Loot' => $this->lowerQuantile($sampled['loots'], 0.2),
111	            'pWin' => $sampled['survived'] / max(1, count($sampled['netProfits'])),
112	            'p20Debris' => $this->lowerQuantile($sampled['debris'], 0.2),
113	        ]);
114	    }
115	
116	    /**
117	     * One bounded screen: the same seed + i stream yields the P20 net (survival),
118	     * the P20 loot (worth-flying) and the survived-run count (fleet survival)
119	     * from identical draws — never a second pass.
120	     *
121	     * @return array{netProfits: list<float>, loots: list<float>, debris: list<float>, survived: int}
122	     */
123	    private function sample(BattleEngine $engine, int $seed, int $samples): array
124	    {
125	        $netProfits = [];
126	        $loots = [];
127	        $debris = [];
128	        $survived = 0;
129	
130	        for ($i = 0; $i < $samples; $i++) {
131	            // One shared stream: seed + i, so a candidate is always compared
132	            // through the same sequence of draws.
133	            $result = $engine->simulateBattle($seed + $i, true);
134	
135	            $loots[] = $this->metalEquivalent($result->loot);
136	            $debris[] = isset($result->debris) ? $this->metalEquivalent($result->debris) : 0.0;
137	            $netProfits[] = $loots[$i] - $this->metalEquivalent($result->attackerResourceLoss);
138	
139	            // getAmount(), not ->units === []: the round sanitizer keeps
140	            // zero-amount entries, so a wiped fleet reads as an empty amount.
141	            $survived += $result->attackerUnitsResult->getAmount() > 0 ? 1 : 0;
142	        }
143	
144	        return ['netProfits' => $netProfits, 'loots' => $loots, 'debris' => $debris, 'survived' => $survived];
145	    }
146	
147	    /**
148	     * @param list<float> $values
149	     */
150	    private function lowerQuantile(array $values, float $quantile): float
151	    {
152	        sort($values);
153	        $rank = (int) ceil($quantile * count($values)) - 1;
154	
155	        return $values[max(0, min($rank, count($values) - 1))];
156	    }
157	
158	    public function metalEquivalent(Resources $resources): float
159	    {
160	        return $resources->metal->get()
161	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
162	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
163	    }
164	}

