 23	/**
 24	 * Module-owned adapter over the host's attack fleet path.
 25	 *
 26	 * The decision and the target are the module's; the mission, its legality and the
 27	 * battle itself are the host's. The raiding fleet is the origin planet's own
 28	 * ships, deducted atomically by the host's mission start.
 29	 */
 30	class QueueAiRaidAction implements QueueAiRaid
 31	{
 32	    /** The farming doctrine, which also states what the launch-time activity dot guards. */
 33	    private const FARM_POLICY_FILE = '/resources/behavior/farm.yaml';
 34	
 35	    public function __construct(
 36	        private PlayerGameStateService $playerGameStateService,
 37	        private PlanetServiceFactory $planetServiceFactory,
 38	        private ActivityIntelReader $activityIntelReader,
 39	    ) {
 40	    }
 41	
 42	    public function handle(int $playerId, int $originPlanetId, int $targetGalaxy, int $targetSystem, int $targetPosition, int $targetType, ?array $launchUnits = null): AiActionResult
 43	    {
 44	        if (!Planet::query()->whereKey($originPlanetId)->where('user_id', $playerId)->exists()) {
 45	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 46	        }
 47	
 48	        try {
 49	            $player = $this->playerGameStateService->advance($playerId, $originPlanetId);
 50	
 51	            if ($player->isBanned()) {
 52	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 53	            }
 54	            if ($player->isInVacationMode()) {
 55	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 56	            }
 57	
 58	            $origin = $this->planetServiceFactory->makeForPlayer($player, $originPlanetId, false);
 59	
 60	            $targetCoordinate = new Coordinate($targetGalaxy, $targetSystem, $targetPosition);
 61	
 62	            $target = $this->planetServiceFactory->makeForCoordinate($targetCoordinate, false, PlanetType::from($targetType));
 63	
 64	            // Between planning and dispatch the target may have logged in. The activity
 65	            // dot only protects what an owner at the keyboard can still move out of the
 66	            // way, and only the farm doctrine says which assets those are: a parked fleet
 67	            // is fleetsaved, while the stock and the wall cannot dodge. Flying into a
 68	            // recall or a ninja is still avoided by the moon-staging gate below and the
 69	            // phalanx gate at planning time (RAID-010).
 70	            if ($target !== null && $this->activityIntelReader->activityAt($target) && $this->ownerCanMoveAssets($target)) {
 71	                return AiActionResult::rejected(AiQueueActionReason::TargetActiveAtDispatch);
 72	            }
 73	
 74	            // A moon active while its planet is quiet is the defender moving a
 75	            // fleet on the moon — staging the trap a raid would fly into
 76	            // (NIN-005). Flying into it is a ninja, not a raid.
 77	            $moon = $this->planetServiceFactory->makeMoonForCoordinate($targetCoordinate);
 78	            if ($moon !== null && $target !== null && $this->activityIntelReader->moonOnlyActivity($moon, $target)) {
 79	                return AiActionResult::rejected(AiQueueActionReason::TargetStagingAtDispatch);
 80	            }
 81	
 82	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
 83	            $fleet = $this->launchFleet($origin, $launchUnits);
 84	
 85	            // The host refuses a flight the origin cannot pay the fuel for; spending deuterium on
 86	            // mines or ferries between planning and dispatch is how a planned raid ends up here.
 87	            $fuel = (float) $fleetMissions->calculateConsumption($origin, $fleet, $targetCoordinate, 0, 10.0);
 88	            if ($fuel > floor($origin->deuterium()->get())) {
 89	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 90	            }
 91	
 92	            $mission = $fleetMissions->createNewFromPlanet(
 93	                $origin,
 94	                $targetCoordinate,
 95	                PlanetType::from($targetType),
 96	                AttackMission::getTypeId(),
 97	                $fleet,
 98	                new Resources(),
 99	                10,
100	            );
101	
102	            return AiActionResult::queued($mission->id);
103	        } catch (Exception $exception) {
104	            return AiActionResult::rejected($exception->getMessage());
105	        }
106	    }
107	
108	    /**
109	     * Whether the target's owner, being at the keyboard, can still move what the raid came for.
110	     *
111	     * A parked fleet is fleetsaved away, so the dot stops the raid; a hold of resources and a
112	     * wall cannot move, so the raid flies and the owner is left to watch it land. The farm
113	     * doctrine names which assets the dot guards, so a server can change the answer there.
114	     */
115	    private function ownerCanMoveAssets(PlanetService $target): bool
116	    {
117	        $guarded = $this->launchActivityGuard();
118	
119	        if (($guarded['fleet'] ?? true) && $target->getShipUnits()->units !== []) {
120	            return true;
121	        }
122	
123	        if (($guarded['defence'] ?? false) && $target->getDefenseUnits()->units !== []) {
124	            return true;
125	        }
126	
127	        return ($guarded['resources'] ?? false) && $target->getResources()->any();
128	    }
129	
130	    /** @return array<string, bool> the assets the launch-time activity dot guards, from the farm doctrine */
131	    private function launchActivityGuard(): array
132	    {
133	        $policy = Yaml::parseFile(module_path('AI', self::FARM_POLICY_FILE));
134	
135	        return is_array($policy['launch_activity_guard'] ?? null) ? $policy['launch_activity_guard'] : [];
136	    }
137	
138	    /**
139	     * The fleet the raid flies: the counter-selected subset, or the whole origin fleet when the
140	     * intent carried no subset (an older work item). The host still owns what the planet holds.
141	     *
142	     * @param array<string, int>|null $launchUnits
143	     */
144	    private function launchFleet(PlanetService $origin, ?array $launchUnits): UnitCollection
145	    {
146	        if ($launchUnits === null || $launchUnits === []) {
147	            return $origin->getShipUnits();
148	        }
149	
150	        $fleet = new UnitCollection();
151	        foreach ($launchUnits as $machineName => $amount) {
152	            if ($amount > 0) {
153	                $fleet->addUnit(ObjectService::getUnitObjectByMachineName($machineName), $amount);
154	            }
155	        }
156	
157	        return $fleet->units === [] ? $origin->getShipUnits() : $fleet;
158	    }
